    AnalysisError("alter table functional.alltypes set location 'blah:///warehouse/'", "No FileSystem for scheme: blah");
    AnalysisError("alter table functional.alltypes set location ''", "URI path cannot be empty.");
    AnalysisError("alter table functional.alltypes set location '      '", "URI path cannot be empty.");
