    testDecimalExpr(decimal_5_5 + " / " + decimal_10_0, ScalarType.createDecimalType(16, 16));
    testDecimalExpr(decimal_5_5 + " % " + decimal_10_0, ScalarType.createDecimalType(5, 5));
    // Test some overflow cases.
    testDecimalExpr(decimal_10_0 + " + " + decimal_38_34, ScalarType.createDecimalType(38, 34), ScalarType.createDecimalType(38, 27));
    testDecimalExpr(decimal_10_0 + " - " + decimal_38_34, ScalarType.createDecimalType(38, 34), ScalarType.createDecimalType(38, 27));
    testDecimalExpr(decimal_10_0 + " * " + decimal_38_34, ScalarType.createDecimalType(38, 34), ScalarType.createDecimalType(38, 23));
    testDecimalExpr(decimal_10_0 + " / " + decimal_38_34, ScalarType.createDecimalType(38, 34), ScalarType.createDecimalType(38, 6));
    testDecimalExpr(decimal_10_0 + " % " + decimal_38_34, ScalarType.createDecimalType(38, 34));
    testDecimalExpr(decimal_38_34 + " + " + decimal_5_5, ScalarType.createDecimalType(38, 34), ScalarType.createDecimalType(38, 33));
    testDecimalExpr(decimal_38_34 + " - " + decimal_5_5, ScalarType.createDecimalType(38, 34), ScalarType.createDecimalType(38, 33));
    testDecimalExpr(decimal_38_34 + " * " + decimal_5_5, ScalarType.createDecimalType(38, 38), ScalarType.createDecimalType(38, 33));
    testDecimalExpr(decimal_38_34 + " / " + decimal_5_5, ScalarType.createDecimalType(38, 34), ScalarType.createDecimalType(38, 29));
    testDecimalExpr(decimal_38_34 + " % " + decimal_5_5, ScalarType.createDecimalType(34, 34));
    testDecimalExpr(decimal_10_0 + " + " + decimal_10_0 + " + " + decimal_10_0, ScalarType.createDecimalType(12, 0));
    testDecimalExpr(decimal_10_0 + " - " + decimal_10_0 + " * " + decimal_10_0, ScalarType.createDecimalType(21, 0), ScalarType.createDecimalType(22, 0));
    testDecimalExpr(decimal_10_0 + " / " + decimal_10_0 + " / " + decimal_10_0, ScalarType.createDecimalType(32, 22));
    testDecimalExpr(decimal_10_0 + " % " + decimal_10_0 + " + " + decimal_10_0, ScalarType.createDecimalType(11, 0));
    // Operators between decimal and numeric types should be supported. The int
    // should be cast to the appropriate decimal (e.g. tinyint -> decimal(3,0)).
    testDecimalExpr(decimal_10_0 + " + cast(1 as tinyint)", ScalarType.createDecimalType(11, 0));
    testDecimalExpr(decimal_10_0 + " + cast(1 as smallint)", ScalarType.createDecimalType(11, 0));
    testDecimalExpr(decimal_10_0 + " + cast(1 as int)", ScalarType.createDecimalType(11, 0));
    testDecimalExpr(decimal_10_0 + " + cast(1 as bigint)", ScalarType.createDecimalType(20, 0));
    testDecimalExpr(decimal_10_0 + " + cast(1 as float)", ScalarType.createDecimalType(38, 9), ScalarType.createDecimalType(38, 8));
    testDecimalExpr(decimal_10_0 + " + cast(1 as double)", ScalarType.createDecimalType(38, 17), ScalarType.createDecimalType(38, 16));
    testDecimalExpr(decimal_5_5 + " + cast(1 as tinyint)", ScalarType.createDecimalType(9, 5));
    testDecimalExpr(decimal_5_5 + " - cast(1 as smallint)", ScalarType.createDecimalType(11, 5));
    testDecimalExpr(decimal_5_5 + " * cast(1 as int)", ScalarType.createDecimalType(15, 5), ScalarType.createDecimalType(16, 5));
    testDecimalExpr(decimal_5_5 + " % cast(1 as bigint)", ScalarType.createDecimalType(5, 5));
    testDecimalExpr(decimal_5_5 + " / cast(1 as float)", ScalarType.createDecimalType(38, 9), ScalarType.createDecimalType(38, 29));
    testDecimalExpr(decimal_5_5 + " + cast(1 as double)", ScalarType.createDecimalType(38, 17), ScalarType.createDecimalType(38, 16));
    AnalyzesOk("select " + decimal_5_5 + " = cast(1 as tinyint)");
    AnalyzesOk("select " + decimal_5_5 + " != cast(1 as smallint)");
    AnalyzesOk("select " + decimal_5_5 + " > cast(1 as int)");
    AnalyzesOk("select " + decimal_5_5 + " < cast(1 as bigint)");
    AnalyzesOk("select " + decimal_5_5 + " >= cast(1 as float)");
    AnalyzesOk("select " + decimal_5_5 + " <= cast(1 as double)");
    AnalysisError("select " + decimal_5_5 + " + 'abcd'", "Arithmetic operation requires numeric operands: " + "CAST(1 AS DECIMAL(5,5)) + 'abcd'");
    AnalysisError("select " + decimal_5_5 + " + 'cast(1 as timestamp)'", "Arithmetic operation requires numeric operands: " + "CAST(1 AS DECIMAL(5,5)) + 'cast(1 as timestamp)'");
    AnalysisError("select " + decimal_5_5 + " = 'abcd'", "operands of type DECIMAL(5,5) and STRING are not comparable: " + "CAST(1 AS DECIMAL(5,5)) = 'abcd'");
    AnalysisError("select " + decimal_5_5 + " > 'cast(1 as timestamp)'", "operands of type DECIMAL(5,5) and STRING are not comparable: " + "CAST(1 AS DECIMAL(5,5)) > 'cast(1 as timestamp)'");
    // IMPALA-7254: Inconsistent decimal behavior when finding a compatible type.
    // for casting.
    // In predicate that does not result in a new precision.
    AnalyzesOk("select cast(2 as double) in " + "(cast(2 as decimal(38, 37)), cast(3 as decimal(38, 37)))");
    AnalyzesOk("select cast(2 as decimal(38, 37)) in " + "(cast(2 as double), cast(3 as decimal(38, 37)))");
    AnalyzesOk("select cast(2 as decimal(38, 37)) in " + "(cast(2 as decimal(38, 37)), cast(3 as double))");
    // In predicate that results in a precision.
    AnalyzesOk("select cast(2 as double) in " + "(cast(2 as decimal(5, 3)), cast(3 as decimal(10, 5)))");
    AnalyzesOk("select cast(2 as decimal(5, 3)) in " + "(cast(2 as double), cast(3 as decimal(10, 5)))");
    AnalyzesOk("select cast(2 as decimal(5, 3)) in " + "(cast(2 as decimal(10, 5)), cast(3 as double))");
    // In predicate that results in a loss of precision.
    AnalysisError("select cast(2 as decimal(38, 37)) in (cast(2 as decimal(38, 1)))", "Incompatible return types 'DECIMAL(38,37)' and 'DECIMAL(38,1)' of exprs " + "'CAST(2 AS DECIMAL(38,37))' and 'CAST(2 AS DECIMAL(38,1))'");
    AnalyzesOk("select cast(2 as double) in " + "(cast(2 as decimal(38, 37)), cast(3 as decimal(38, 1)))");
    AnalyzesOk("select cast(2 as decimal(38, 37)) in " + "(cast(2 as double), cast(3 as decimal(38, 1)))");
    AnalyzesOk("select cast(2 as decimal(38, 37)) in " + "(cast(2 as decimal(38, 1)), cast(3 as double))");
}

