@Test
public void TestComplexTypesInSelectList() {
    // Star only expands to the scalar-typed fields.
    AnalyzesOk("select * from functional.allcomplextypes " + "cross join functional_parquet.alltypes");
    AnalyzesOk("select complex_struct_col.* from functional.allcomplextypes");
    // The result exprs could be empty after star expansion.
    addTestTable("create table only_complex_types " + "(a array<int>, b struct<x:int, y:int>, c map<string, int>)");
    AnalysisError("select * from only_complex_types", "The star exprs expanded to an empty select list because the referenced " + "tables only have complex-typed columns.");
    AnalysisError("select a.* from only_complex_types a, " + "functional.allcomplextypes b", "The star exprs expanded to an empty select list because the referenced " + "tables only have complex-typed columns.");
    // Empty star expansion, but non empty result exprs.
    AnalyzesOk("select 1, * from only_complex_types");
    // Illegal complex-typed expr in select list.
    AnalysisError("select int_struct_col from functional.allcomplextypes", "Expr 'int_struct_col' in select list returns a " + "complex type 'STRUCT<f1:INT,f2:INT>'.\n" + "Only scalar types are allowed in the select list.");
    // Illegal complex-typed expr in a union.
    AnalysisError("select int_struct_col from functional.allcomplextypes " + "union all select int_struct_col from functional.allcomplextypes", "Expr 'int_struct_col' in select list returns a " + "complex type 'STRUCT<f1:INT,f2:INT>'.\n" + "Only scalar types are allowed in the select list.");
    // Illegal complex-typed expr inside inline view.
    AnalysisError("select 1 from " + "(select int_struct_col from functional.allcomplextypes) v", "Expr 'int_struct_col' in select list returns a " + "complex type 'STRUCT<f1:INT,f2:INT>'.\n" + "Only scalar types are allowed in the select list.");
    // Illegal complex-typed expr in an insert.
    AnalysisError("insert into functional.allcomplextypes " + "select int_struct_col from functional.allcomplextypes", "Expr 'int_struct_col' in select list returns a " + "complex type 'STRUCT<f1:INT,f2:INT>'.\n" + "Only scalar types are allowed in the select list.");
    // Illegal complex-typed expr in a CTAS.
    AnalysisError("create table new_tbl as " + "select int_struct_col from functional.allcomplextypes", "Expr 'int_struct_col' in select list returns a " + "complex type 'STRUCT<f1:INT,f2:INT>'.\n" + "Only scalar types are allowed in the select list.");
}

@Test
public void TestAliasesAndOrdinals() throws AnalysisException {
    AnalysisError("select * from functional.alltypes group by 1", "cannot combine '*' in select list with grouping or aggregation");
    AnalysisError("select * from functional.alltypes order by 14", "ORDER BY: ordinal exceeds number of items in select list: 14");
    AnalyzesOk("select t.* from functional.alltypes t order by 1");
    AnalyzesOk("select t2.* from functional.alltypes t1, " + "functional.alltypes t2 order by 1");
    AnalyzesOk("select * from (select max(id) from functional.testtbl) t1 order by 1");
    AnalysisError("select * from (select max(id) from functional.testtbl) t1 order by 2", "ORDER BY: ordinal exceeds number of items in select list: 2");
    // IMPALA-5191: In GROUP BY, HAVING, ORDER BY, aliases and ordinals must only be
    // substituted at the top level
    // Ambiguous alias in HAVING
    AnalysisError("select not bool_col m, min(smallint_col) m, max(bigint_col) m " + "from functional.alltypes group by bool_col having m", "Column 'm' in HAVING clause is ambiguous");
    // GROUP BY, ORDER BY, HAVING contains top-level SlotRef or ordinal
    AnalyzesOk("select int_col / 2 as x from functional.alltypes group by x");
    AnalyzesOk("select int_col / 2 as x from functional.alltypes order by x");
    AnalyzesOk("select not bool_col as nb from functional.alltypes having nb");
    AnalyzesOk("select int_col / 2 as x from functional.alltypes group by 1");
    AnalyzesOk("select int_col / 2 as x from functional.alltypes order by 1");
    AnalyzesOk("select not bool_col as nb from functional.alltypes having 1");
    // GROUP BY, ORDER BY, HAVING contains alias in subexpression
    AnalysisError("select int_col / 2 as x from functional.alltypes group by x / 2", "Could not resolve column/field reference: 'x'");
    AnalysisError("select int_col / 2 as x from functional.alltypes order by -x", "Could not resolve column/field reference: 'x'");
    AnalysisError("select int_col / 2 as x from functional.alltypes having x > 0", "Could not resolve column/field reference: 'x'");
    // Alias or ordinal referring to aggregation output in GROUP BY, ORDER BY, HAVING
    AnalysisError("select count(*) a from functional.alltypes group by a", "GROUP BY expression must not contain aggregate functions: a");
    AnalyzesOk("select count(*) a from functional.alltypes order by a");
    AnalysisError("select count(*) a from functional.alltypes having a", "HAVING clause 'count(*)' requires return type 'BOOLEAN'. " + "Actual type is 'BIGINT'.");
    AnalysisError("select count(*) from functional.alltypes group by 1", "GROUP BY expression must not contain aggregate functions: 1");
    AnalyzesOk("select count(*) from functional.alltypes order by 1");
    AnalysisError("select count(*) from functional.alltypes having 1", "HAVING clause 'count(*)' requires return type 'BOOLEAN'. " + "Actual type is 'BIGINT'.");
    // Alias or ordinal referring to predicate in GROUP BY, ORDER BY, HAVING
    AnalysisError("select count(*) > 10 a from functional.alltypes group by a", "GROUP BY expression must not contain aggregate functions: a");
    AnalyzesOk("select count(*) > 10 a from functional.alltypes order by a");
    AnalyzesOk("select count(*) > 10 a from functional.alltypes having a");
    AnalysisError("select count(*) > 10 from functional.alltypes group by 1", "GROUP BY expression must not contain aggregate functions: 1");
    AnalyzesOk("select count(*) > 10 from functional.alltypes order by 1");
    AnalyzesOk("select count(*) > 10 from functional.alltypes having 1");
    // Alias or ordinal referring to analytic output in GROUP BY, ORDER BY, HAVING
    AnalysisError("select sum(id) over(order by id) a " + "from functional.alltypes group by a", "GROUP BY expression must not contain analytic expressions: " + "sum(id) OVER (ORDER BY id ASC)");
    AnalyzesOk("select sum(id) over(order by id) a from functional.alltypes order by a");
    AnalysisError("select sum(id) over(order by id) a from functional.alltypes having a", "HAVING clause must not contain analytic expressions: " + "sum(id) OVER (ORDER BY id ASC)");
    AnalysisError("select sum(id) over(order by id) " + "from functional.alltypes group by 1", "GROUP BY expression must not contain analytic expressions: " + "sum(id) OVER (ORDER BY id ASC)");
    AnalyzesOk("select sum(id) over(order by id) from functional.alltypes order by 1");
    AnalysisError("select sum(id) over(order by id) from functional.alltypes having 1", "HAVING clause must not contain analytic expressions: " + "sum(id) OVER (ORDER BY id ASC)");
    AnalyzesOk("with w_test as (select '1' as `one`, 2 as two, '3' as three) " + "select `one` as `one`, substring(cast(two as string), 1, 1) as two, " + "three as three, count(1) as cnt " + "from w_test " + "group by `one`, substring(cast(two as string), 1, 1), three");
    // Constant exprs should not be interpreted as ordinals
    AnalyzesOk("select int_col, count(*) from functional.alltypes group by 1, 1 * 2");
    AnalyzesOk("select int_col, bigint_col from functional.alltypes order by 1 + 4");
    AnalysisError("select int_col, bool_col, count(*) from functional.alltypes " + "group by 1, 2 having 1 + 1", "HAVING clause '1 + 1' requires return type 'BOOLEAN'. " + "Actual type is 'SMALLINT'.");
    AnalyzesOk("select int_col, count(*) from functional.alltypes group by 1, " + "if(true, 2, int_col)");
    AnalyzesOk("select int_col, bigint_col from functional.alltypes order by " + "if(true, 7, int_col)");
    AnalysisError("select int_col, bool_col, count(*) from functional.alltypes " + "group by 1, 2 having if(TRUE, 2, int_col)", "HAVING clause 'if(TRUE, 2, int_col)' requires return type 'BOOLEAN'. " + "Actual type is 'INT'.");
}

@Test
public void TestInlineView() throws AnalysisException {
    AnalyzesOk("select y x from (select id y from functional_hbase.alltypessmall) a");
    AnalyzesOk("select id from (select id from functional_hbase.alltypessmall) a");
    AnalyzesOk("select * from (select id+2 from functional_hbase.alltypessmall) a");
    AnalyzesOk("select t1 c from " + "(select c t1 from (select id c from functional_hbase.alltypessmall) t1) a");
    AnalysisError("select id from (select id+2 from functional_hbase.alltypessmall) a", "Could not resolve column/field reference: 'id'");
    AnalyzesOk("select a.* from (select id+2 from functional_hbase.alltypessmall) a");
    // join test
    AnalyzesOk("select * from (select id+2 id from functional_hbase.alltypessmall) a " + "join (select * from functional.AllTypes where true) b");
    AnalyzesOk("select a.x from (select count(id) x from functional.AllTypes) a");
    AnalyzesOk("select a.* from (select count(id) from functional.AllTypes) a");
    AnalysisError("select a.id from (select id y from functional_hbase.alltypessmall) a", "Could not resolve column/field reference: 'a.id'");
    AnalyzesOk("select * from (select * from functional.AllTypes) a where year = 2009");
    AnalyzesOk("select * from (select * from functional.alltypesagg) a right outer join" + "             (select * from functional.alltypessmall) b using (id, int_col) " + "       where a.day >= 6 and b.month > 2 and a.tinyint_col = 15 and " + "             b.string_col = '15' and a.tinyint_col + b.tinyint_col < 15");
    AnalyzesOk("select * from (select a.smallint_col+b.smallint_col  c1" + "         from functional.alltypesagg a join functional.alltypessmall b " + "         using (id, int_col)) x " + "         where x.c1 > 100");
    AnalyzesOk("select a.* from" + " (select * from (select id+2 from functional_hbase.alltypessmall) b) a");
    AnalysisError("select * from " + "(select * from functional.alltypes a join " + "functional.alltypes b on (a.int_col = b.int_col)) x", "duplicated inline view column alias: 'id' in inline view 'x'");
    // subquery on the rhs of the join
    AnalyzesOk("select x.float_col " + "       from functional.alltypessmall c join " + "          (select a.smallint_col smallint_col, a.tinyint_col tinyint_col, " + "                   a.int_col int_col, b.float_col float_col" + "          from (select * from functional.alltypesagg a where month=1) a join " + "                  functional.alltypessmall b on (a.smallint_col = b.id)) x " + "            on (x.tinyint_col = c.id)");
    // aggregate test
    AnalyzesOk("select count(*) from (select count(id) from " + "functional.AllTypes group by id) a");
    AnalyzesOk("select count(a.x) from (select id+2 x " + "from functional_hbase.alltypessmall) a");
    AnalyzesOk("select * from (select id, zip " + "       from (select * from functional.testtbl) x " + "       group by zip, id having count(*) > 0) x");
    AnalysisError("select zip + count(*) from functional.testtbl", "select list expression not produced by aggregation output " + "(missing from GROUP BY clause?)");
    // union test
    AnalyzesOk("select a.* from " + "(select rank() over(order by string_col) from functional.alltypes " + " union all " + " select tinyint_col from functional.alltypessmall) a");
    AnalyzesOk("select a.* from " + "(select int_col from functional.alltypes " + " union all " + " select tinyint_col from functional.alltypessmall) a " + "union all " + "select smallint_col from functional.alltypes");
    AnalyzesOk("select a.* from " + "(select int_col from functional.alltypes " + " union all " + " select b.smallint_col from " + "  (select smallint_col from functional.alltypessmall" + "   union all" + "   select tinyint_col from functional.alltypes) b) a");
    // negative union test, column labels are inherited from first select block
    AnalysisError("select tinyint_col from " + "(select int_col from functional.alltypes " + " union all " + " select tinyint_col from functional.alltypessmall) a", "Could not resolve column/field reference: 'tinyint_col'");
    // negative aggregate test
    AnalysisError("select * from " + "(select id, zip from functional.testtbl group by id having count(*) > 0) x", "select list expression not produced by aggregation output " + "(missing from GROUP BY clause?)");
    AnalysisError("select * from " + "(select id from functional.testtbl group by id having zip + count(*) > 0) x", "HAVING clause not produced by aggregation output " + "(missing from GROUP BY clause?)");
    AnalysisError("select * from " + "(select zip, count(*) from functional.testtbl group by 3) x", "GROUP BY: ordinal exceeds number of items in select list");
    AnalysisError("select * from " + "(select * from functional.alltypes group by 1) x", "cannot combine '*' in select list with grouping or aggregation");
    AnalysisError("select * from " + "(select zip, count(*) from functional.testtbl group by count(*)) x", "GROUP BY expression must not contain aggregate functions");
    AnalysisError("select * from " + "(select zip, count(*) from functional.testtbl group by count(*) + min(zip)) x", "GROUP BY expression must not contain aggregate functions");
    AnalysisError("select * from " + "(select zip, count(*) from functional.testtbl group by 2) x", "GROUP BY expression must not contain aggregate functions");
    // order by, top-n
    AnalyzesOk("select * from (select zip, count(*) " + "       from (select * from functional.testtbl) x " + "       group by 1 order by count(*) + min(zip) limit 5) x");
    AnalyzesOk("select * from (select zip, count(*) " + "       from (select * from functional.testtbl) x " + "       group by 1 order by count(*) + min(zip)) x");
    AnalysisError("select * from (select zip, count(*) " + "       from (select * from functional.testtbl) x " + "       group by 1 offset 5) x", "OFFSET requires an ORDER BY clause: OFFSET 5");
    AnalysisError("select * from (select zip, count(*) " + "       from (select * from functional.testtbl) x " + "       group by 1 order by count(*) + min(zip) offset 5) x", "Order-by with offset without limit not supported in nested queries");
    AnalyzesOk("select c1, c2 from (select zip c1 , count(*) c2 " + "                     from (select * from functional.testtbl) x group by 1) x " + "        order by 2, 1 limit 5");
    AnalyzesOk("select c1, c2 from (select zip c1 , count(*) c2 " + "                     from (select * from functional.testtbl) x group by 1) x " + "        order by 2, 1");
    AnalyzesOk("select c1, c2 from (select zip c1 , count(*) c2 " + "                     from (select * from functional.testtbl) x group by 1) x " + "        order by 2, 1 offset 5");
    // test NULLs
    AnalyzesOk("select * from (select NULL) a");
    // test that auto-generated columns are not used by default
    AnalyzesOk("select `int_col * 1`, a, int_col, `NOT bool_col` from " + "(select int_col * 1, int_col as a, int_col, !bool_col, concat(string_col) " + "from functional.alltypes) t");
    // test auto-generated column labels by enforcing their use in inline views
    AnalyzesOk("select _c0, a, int_col, _c3 from " + "(select int_col * 1, int_col as a, int_col, !bool_col, concat(string_col) " + "from functional.alltypes) t", createAnalysisCtxUsingHiveColLabels());
    // test auto-generated column labels in group by and order by
    AnalyzesOk("select _c0, count(a), count(int_col), _c3 from " + "(select int_col * 1, int_col as a, int_col, !bool_col, concat(string_col) " + "from functional.alltypes) t group by _c0, _c3 order by _c0 limit 10", createAnalysisCtxUsingHiveColLabels());
    // test auto-generated column labels in multiple scopes
    AnalyzesOk("select x.front, x._c1, x._c2 from " + "(select y.back as front, y._c0 * 10, y._c2 + 2 from " + "(select int_col * 10, int_col as back, int_col + 2 from " + "functional.alltypestiny) y) x", createAnalysisCtxUsingHiveColLabels());
    // IMPALA-3537: Test that auto-generated column labels are only applied in
    // the appropriate child query blocks.
    SelectStmt colLabelsStmt = (SelectStmt) AnalyzesOk("select avg(int_col) from functional.alltypes_view");
    assertEquals("avg(int_col)", colLabelsStmt.getColLabels().get(0));
    AnalyzesOk("select `max(int_col)` from " + "(select max(int_col) from functional.alltypes_view) v");
    // ambiguous reference to an auto-generated column
    AnalysisError("select _c0 from " + "(select int_col * 2, id from functional.alltypes) a inner join " + "(select int_col + 6, id from functional.alltypes) b " + "on (a.id = b.id)", createAnalysisCtxUsingHiveColLabels(), "Column/field reference is ambiguous: '_c0'");
    // auto-generated column doesn't exist
    AnalysisError("select _c0, a, _c2, _c3 from " + "(select int_col * 1, int_col as a, int_col, !bool_col, concat(string_col) " + "from functional.alltypes) t", createAnalysisCtxUsingHiveColLabels(), "Could not resolve column/field reference: '_c2'");
    // Regression test for IMPALA-984.
    AnalyzesOk("SELECT 1 " + "FROM functional.decimal_tbl AS t1 LEFT JOIN " + "(SELECT SUM(t1.d2) - SUM(t1.d3) as double_col_3, " + "SUM(t1.d2) IS NULL " + "FROM functional.decimal_tbl AS t1) AS t3 " + "ON t3.double_col_3 = t1.d3");
    // Test that InlineViewRef.makeOutputNullable() preserves expr signatures when
    // substituting NULL literals for SlotRefs (IMPALA-1468).
    AnalyzesOk("select 1 from functional.alltypes a left outer join " + "(select id, upper(decode(string_col, NULL, date_string_col)) " + "from functional.alltypes) v on (a.id = v.id)");
    // Inline view with a subquery
    AnalyzesOk("select y x from " + "(select id y from functional.alltypestiny where id in " + "(select id from functional.alltypessmall)) a");
}

@Test
public void TestCorrelatedInlineViews() {
    // Basic inline view with a single correlated table ref.
    AnalyzesOk("select cnt from functional.allcomplextypes t, " + "(select count(*) cnt from t.int_array_col) v");
    AnalyzesOk("select cnt from functional.allcomplextypes t, " + "(select cnt from (select count(*) cnt from t.int_array_col) v1) v2");
    AnalyzesOk("select item from functional.allcomplextypes t, " + "(select item from t.array_map_col.value) v");
    // Multiple nesting levels.
    AnalyzesOk("select item from functional.allcomplextypes t, " + "(select * from (select * from (select item from t.int_array_col) v1) v2) v3");
    // Mixing correlated and uncorrelated inline views in the same select block works.
    AnalyzesOk("select v.cnt from functional.allcomplextypes t1 " + "join (select * from functional.alltypes) t2 on (t1.id = t2.id) " + "cross join (select count(*) cnt from t1.int_map_col) v");
    // Multiple correlated table refs.
    AnalyzesOk("select avg from functional.allcomplextypes t, " + "(select avg(a1.item) avg from t.int_array_col a1, t.int_array_col a2) v");
    AnalyzesOk("select item, key, value from functional.allcomplextypes t, " + "(select * from t.int_array_col, t.int_map_col) v");
    // Correlated inline view inside uncorrelated inline view.
    AnalyzesOk("select cnt from functional.alltypes t1 inner join " + "(select id, cnt from functional.allcomplextypes t2, " + "(select count(1) cnt from t2.int_array_col) v1) v2");
    // Correlated table ref has child ref itself.
    AnalyzesOk("select key, item from functional.allcomplextypes t, " + "(select a1.key, a2.item from t.array_map_col a1, a1.value a2) v");
    AnalyzesOk("select key, av from functional.allcomplextypes t, " + "(select a1.key, av from t.array_map_col a1, " + "(select avg(item) av from a1.value a2) v1) v2");
    // TODO: Enable once we support complex-typed exprs in the select list.
    //AnalyzesOk("select key, av from functional.allcomplextypes t, " +
    //    "(select a1.key, a1.value from t.array_map_col a1) v1, " +
    //    "(select avg(item) av from v1.value) v2");
    // Multiple correlated table refs with different parents.
    AnalyzesOk("select t1.id, t2.id, cnt, av from functional.allcomplextypes t1 " + "left outer join functional.allcomplextypes t2 on (t1.id = t2.id), " + "(select count(*) cnt from t1.array_map_col) v1, " + "(select avg(item) av from t2.int_array_col) v2");
    // Correlated table refs in a union.
    AnalyzesOk("select item from functional.allcomplextypes t, " + "(select * from t.int_array_col union all select * from t.int_array_col) v");
    AnalyzesOk("select item from functional.allcomplextypes t, " + "(select item from t.int_array_col union distinct " + "select value from t.int_map_col) v");
    // Correlated inline view in WITH-clause.
    AnalyzesOk("with w as (select item from functional.allcomplextypes t, " + "(select item from t.int_array_col) v) " + "select * from w");
    AnalyzesOk("with w as (select key, av from functional.allcomplextypes t, " + "(select a1.key, av from t.array_map_col a1, " + "(select avg(item) av from a1.value a2) v1) v2) " + "select * from w");
    // TODO: Enable once we support complex-typed exprs in the select list.
    //AnalyzesOk("with w as (select key, av from functional.allcomplextypes t, " +
    //    "(select a1.key, a1.value from t.array_map_col a1) v1, " +
    //    "(select avg(item) av from v1.value) v2) " +
    //    "select * from w");
    // Test behavior of aliases in correlated inline views.
    // Inner reference resolves to the base table, not the implicit parent alias.
    AnalyzesOk("select cnt from functional.allcomplextypes t, " + "(select count(1) cnt from functional.allcomplextypes) v");
    AnalyzesOk("select cnt from functional.allcomplextypes, " + "(select count(1) cnt from functional.allcomplextypes) v");
    AnalyzesOk("select cnt from functional.allcomplextypes, " + "(select count(1) cnt from allcomplextypes) v", createAnalysisCtx("functional"));
    // Illegal correlated reference.
    AnalysisError("select cnt from functional.allcomplextypes t, " + "(select count(1) cnt from t) v", "Illegal table reference to non-collection type: 't'");
    AnalysisError("select cnt from functional.allcomplextypes, " + "(select count(1) cnt from allcomplextypes) v", "Illegal table reference to non-collection type: 'allcomplextypes'");
    // Un/correlated refs in a single nested query block.
    AnalysisError("select cnt from functional.allcomplextypes t, " + "(select count(1) cnt from functional.alltypes, t.int_array_col) v", "Nested query is illegal because it contains a table reference " + "'t.int_array_col' correlated with an outer block as well as an " + "uncorrelated one 'functional.alltypes':\n" + "SELECT count(1) cnt FROM functional.alltypes, t.int_array_col");
    AnalysisError("select cnt from functional.allcomplextypes t, " + "(select count(1) cnt from t.int_array_col, functional.alltypes) v", "Nested query is illegal because it contains a table reference " + "'t.int_array_col' correlated with an outer block as well as an " + "uncorrelated one 'functional.alltypes':\n" + "SELECT count(1) cnt FROM t.int_array_col, functional.alltypes");
    // Un/correlated refs across multiple nested query blocks.
    AnalysisError("select cnt from functional.allcomplextypes t, " + "(select * from functional.alltypes, " + "(select count(1) cnt from t.int_array_col) v1) v2", "Nested query is illegal because it contains a table reference " + "'t.int_array_col' correlated with an outer block as well as an " + "uncorrelated one 'functional.alltypes':\n" + "SELECT * FROM functional.alltypes, (SELECT count(1) cnt " + "FROM t.int_array_col) v1");
    // TODO: Enable once we support complex-typed exprs in the select list.
    // Correlated table ref has correlated inline view as parent.
    //AnalysisError("select cnt from functional.allcomplextypes t, " +
    //    "(select value arr from t.array_map_col) v1, " +
    //    "(select item from v1.arr, functional.alltypestiny) v2",
    //    "Nested query is illegal because it contains a table reference " +
    //    "'v1.arr' correlated with an outer block as well as an " +
    //    "uncorrelated one 'functional.alltypestiny':\n" +
    //    "SELECT item FROM v1.arr, functional.alltypestiny");
    // Un/correlated refs in union operands.
    AnalysisError("select cnt from functional.allcomplextypes t, " + "(select bigint_col from functional.alltypes " + "union select count(1) cnt from t.int_array_col) v1", "Nested query is illegal because it contains a table reference " + "'t.int_array_col' correlated with an outer block as well as an " + "uncorrelated one 'functional.alltypes':\n" + "SELECT bigint_col FROM functional.alltypes " + "UNION SELECT count(1) cnt FROM t.int_array_col");
    // Un/correlated refs in WITH-clause view.
    AnalysisError("with w as (select cnt from functional.allcomplextypes t, " + "(select count(1) cnt from t.int_array_col, functional.alltypes) v) " + "select * from w", "Nested query is illegal because it contains a table reference " + "'t.int_array_col' correlated with an outer block as well as an " + "uncorrelated one 'functional.alltypes':\n" + "SELECT count(1) cnt FROM t.int_array_col, functional.alltypes");
    // Test that joins without an ON clause analyze ok if the rhs table is correlated.
    for (JoinOperator joinOp : JoinOperator.values()) {
        if (joinOp.isNullAwareLeftAntiJoin())
            continue;
        AnalyzesOk(String.format("select 1 from functional.allcomplextypes a %s " + "(select item from a.int_array_col) v", joinOp));
        AnalyzesOk(String.format("select 1 from functional.allcomplextypes a %s " + "(select * from a.struct_array_col) v", joinOp));
        AnalyzesOk(String.format("select 1 from functional.allcomplextypes a %s " + "(select key, value from a.int_map_col) v", joinOp));
        AnalyzesOk(String.format("select 1 from functional.allcomplextypes a %s " + "(select * from a.struct_map_col) v", joinOp));
    }
}

@Test
public void TestOnClause() throws AnalysisException {
    AnalyzesOk("select a.int_col from functional.alltypes a " + "join functional.alltypes b on (a.int_col = b.int_col)");
    AnalyzesOk("select a.int_col " + "from functional.alltypes a join functional.alltypes b on " + "(a.int_col = b.int_col and a.string_col = b.string_col)");
    AnalyzesOk("select a.int_col from functional.alltypes a " + "join functional.alltypes b on (a.bool_col)");
    AnalyzesOk("select a.int_col from functional.alltypes a " + "join functional.alltypes b on (NULL)");
    // ON or USING clause not required for inner join
    AnalyzesOk("select a.int_col from functional.alltypes a join functional.alltypes b");
    // arbitrary expr not returning bool
    AnalysisError("select a.int_col from functional.alltypes a " + "join functional.alltypes b on trim(a.string_col)", "ON clause 'trim(a.string_col)' requires return type 'BOOLEAN'. " + "Actual type is 'STRING'.");
    AnalysisError("select a.int_col from functional.alltypes a " + "join functional.alltypes b on a.int_col * b.float_col", "ON clause 'a.int_col * b.float_col' requires return type 'BOOLEAN'. " + "Actual type is 'DOUBLE'.");
    // wrong kind of expr
    AnalysisError("select a.int_col from functional.alltypes a " + "join functional.alltypes b on (a.bigint_col = sum(b.int_col))", "aggregate function not allowed in ON clause");
    AnalysisError("select a.int_col from functional.alltypes a " + "join functional.alltypes b on (a.bigint_col = " + "lag(b.int_col) over(order by a.bigint_col))", "analytic expression not allowed in ON clause");
    AnalysisError("select a.int_col from functional.alltypes a " + "join functional.alltypes b on (a.id = b.id) and " + "a.int_col < (select min(id) from functional.alltypes c)", "Subquery is not allowed in ON clause");
    // unknown column
    AnalysisError("select a.int_col from functional.alltypes a " + "join functional.alltypes b on (a.int_col = b.badcol)", "Could not resolve column/field reference: 'b.badcol'");
    // ambiguous col ref
    AnalysisError("select a.int_col from functional.alltypes a " + "join functional.alltypes b on (int_col = int_col)", "Column/field reference is ambiguous: 'int_col'");
    // unknown alias
    AnalysisError("select a.int_col from functional.alltypes a join functional.alltypes b on " + "(a.int_col = badalias.int_col)", "Could not resolve column/field reference: 'badalias.int_col'");
    // incompatible comparison
    AnalysisError("select a.int_col from functional.alltypes a join " + "functional.alltypes b on a.bool_col = b.string_col", "operands of type BOOLEAN and STRING are not comparable: " + "a.bool_col = b.string_col");
    AnalyzesOk("select a.int_col, b.int_col, c.int_col " + "from functional.alltypes a join functional.alltypes b on " + "(a.int_col = b.int_col and a.string_col = b.string_col)" + "join functional.alltypes c on " + "(b.int_col = c.int_col and b.string_col = c.string_col " + "and b.bool_col = c.bool_col)");
    // can't reference an alias that gets declared afterwards
    AnalysisError("select a.int_col, b.int_col, c.int_col " + "from functional.alltypes a join functional.alltypes b on " + "(c.int_col = b.int_col and a.string_col = b.string_col)" + "join functional.alltypes c on " + "(b.int_col = c.int_col and b.string_col = c.string_col " + "and b.bool_col = c.bool_col)", "Could not resolve column/field reference: 'c.int_col'");
    // outer joins require ON/USING clause
    AnalyzesOk("select * from functional.alltypes a left outer join " + "functional.alltypes b on (a.id = b.id)");
    AnalyzesOk("select * from functional.alltypes a left outer join " + "functional.alltypes b using (id)");
    AnalysisError("select * from functional.alltypes a " + "left outer join functional.alltypes b", "LEFT OUTER JOIN requires an ON or USING clause");
    AnalyzesOk("select * from functional.alltypes a right outer join " + "functional.alltypes b on (a.id = b.id)");
    AnalyzesOk("select * from functional.alltypes a right outer join " + "functional.alltypes b using (id)");
    AnalysisError("select * from functional.alltypes a " + "right outer join functional.alltypes b", "RIGHT OUTER JOIN requires an ON or USING clause");
    AnalyzesOk("select * from functional.alltypes a full outer join " + "functional.alltypes b on (a.id = b.id)");
    AnalyzesOk("select * from functional.alltypes a full outer join " + "functional.alltypes b using (id)");
