@Test
public void TestSampledNdv() throws AnalysisException {
    Table allScalarTypes = addAllScalarTypesTestTable();
    String tblName = allScalarTypes.getFullName();
    // Positive tests: Test all scalar types and valid sampling percents.
    double[] validSamplePercs = new double[] { 0.0, 0.1, 0.2, 0.5, 0.8, 1.0 };
    for (double perc : validSamplePercs) {
        List<String> allAggFnCalls = Lists.newArrayList();
        for (Column col : allScalarTypes.getColumns()) {
            String aggFnCall = String.format("sampled_ndv(%s, %s)", col.getName(), perc);
            allAggFnCalls.add(aggFnCall);
            String stmtSql = String.format("select %s from %s", aggFnCall, tblName);
            SelectStmt stmt = (SelectStmt) AnalyzesOk(stmtSql);
            // Verify that the resolved function signature matches as expected.
            Type[] args = stmt.getAggInfo().getAggregateExprs().get(0).getFn().getArgs();
            assertEquals(args.length, 2);
            assertTrue(col.getType().matchesType(args[0]) || col.getType().isStringType() && args[0].equals(Type.STRING));
            assertEquals(Type.DOUBLE, args[1]);
        }
        // Test several calls in the same query block.
        AnalyzesOk(String.format("select %s from %s", Joiner.on(",").join(allAggFnCalls), tblName));
    }
    // Negative tests: Incorrect number of args.
    AnalysisError(String.format("select sampled_ndv() from %s", tblName), "No matching function with signature: sampled_ndv().");
    AnalysisError(String.format("select sampled_ndv(int_col) from %s", tblName), "No matching function with signature: sampled_ndv(INT).");
    AnalysisError(String.format("select sampled_ndv(int_col, 0.1, 10) from %s", tblName), "No matching function with signature: sampled_ndv(INT, DECIMAL(1,1), TINYINT).");
    // Negative tests: Invalid sampling percent.
    String[] invalidSamplePercs = new String[] { "int_col", "double_col", "100 / 10", "-0.1", "1.1", "100", "50", "-50", "NULL" };
    for (String invalidPerc : invalidSamplePercs) {
        AnalysisError(String.format("select sampled_ndv(int_col, %s) from %s", invalidPerc, tblName), "Second parameter of SAMPLED_NDV() must be a numeric literal in [0,1]: " + invalidPerc);
    }
}

@Test
public void TestGroupConcat() throws AnalysisException {
    // Test valid and invalid parameters
    AnalyzesOk("select group_concat(distinct name) from functional.testtbl");
    AnalysisError("select group_concat(distinct name, name) from functional.testtbl", "Second parameter in GROUP_CONCAT(DISTINCT) must be a constant expression" + " that returns a string.");
    AnalyzesOk("select group_concat(distinct name, cast(123 as string)) " + "from functional.testtbl");
    AnalysisError("select group_concat(distinct name, cast(id as string)) " + "from functional.testtbl", "Second parameter in GROUP_CONCAT(DISTINCT) must be a constant expression" + " that returns a string.");
    AnalyzesOk("select group_concat(distinct string_col, concat('-', '?')) " + "from functional.alltypesagg");
    AnalysisError("select group_concat(*) from functional.testtbl", "'*' can only be used in conjunction with COUNT");
    // test group_concat using a column as the custom separator
    AnalyzesOk("select group_concat(string_col, string_col) from functional.alltypes");
    // test group_concat without and with distinct
    String[] keywords = new String[] { "distinct", "" };
    for (String keyword : keywords) {
        AnalysisError(String.format("select group_concat(%s '')", keyword), "aggregation" + " without a FROM clause is not allowed");
        AnalysisError(String.format("select group_concat(%s name, '-', ',') " + "from functional.testtbl", keyword), "No matching function with signature: " + "group_concat(STRING, STRING, STRING)");
        // test all types as arguments
        for (Type type : typeToLiteralValue_.keySet()) {
            String literal = typeToLiteralValue_.get(type);
            String query1 = String.format("select group_concat(%s %s) from functional.alltypes", keyword, literal);
            String query2 = String.format("select group_concat(%s %s, '---') from functional.alltypes", keyword, literal);
            if (type.getPrimitiveType() == PrimitiveType.STRING || type.isNull()) {
                AnalyzesOk(query1);
                AnalyzesOk(query2);
            } else {
                AnalysisError(query1, "No matching function with signature: group_concat(");
                AnalysisError(query2, "No matching function with signature: group_concat(");
            }
        }
    }
}

