@Test
public void TestKuduStatements() throws AuthorizationException, AnalysisException {
    TestUtils.assumeKuduIsSupported();
    // Select
    Set<TAccessEvent> accessEvents = AnalyzeAccessEvents("select * from functional_kudu.testtbl");
    Assert.assertEquals(accessEvents, Sets.newHashSet(new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "SELECT")));
    // Insert
    accessEvents = AnalyzeAccessEvents("insert into functional_kudu.testtbl (id) select id from " + "functional_kudu.alltypes");
    Assert.assertEquals(accessEvents, Sets.newHashSet(new TAccessEvent("functional_kudu.alltypes", TCatalogObjectType.TABLE, "SELECT"), new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "INSERT")));
    // Upsert
    accessEvents = AnalyzeAccessEvents("upsert into functional_kudu.testtbl (id) select id from " + "functional_kudu.alltypes");
    Assert.assertEquals(accessEvents, Sets.newHashSet(new TAccessEvent("functional_kudu.alltypes", TCatalogObjectType.TABLE, "SELECT"), new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "ALL")));
    // Delete
    accessEvents = AnalyzeAccessEvents("delete from functional_kudu.testtbl where id = 1");
    Assert.assertEquals(accessEvents, Sets.newHashSet(new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "SELECT"), new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "ALL")));
    // Delete using a complex query
    accessEvents = AnalyzeAccessEvents("delete c from functional_kudu.testtbl c, functional_kudu.alltypes s where " + "c.id = s.id and s.int_col < 10");
    Assert.assertEquals(accessEvents, Sets.newHashSet(new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "SELECT"), new TAccessEvent("functional_kudu.alltypes", TCatalogObjectType.TABLE, "SELECT"), new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "ALL")));
    // Update
    accessEvents = AnalyzeAccessEvents("update functional_kudu.testtbl set name = 'test' where id < 10");
    Assert.assertEquals(accessEvents, Sets.newHashSet(new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "SELECT"), new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "ALL")));
    // Drop table
    accessEvents = AnalyzeAccessEvents("drop table functional_kudu.testtbl");
    Assert.assertEquals(accessEvents, Sets.newHashSet(new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "DROP")));
    // Show create table
    accessEvents = AnalyzeAccessEvents("show create table functional_kudu.testtbl");
    Assert.assertEquals(accessEvents, Sets.newHashSet(new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "VIEW_METADATA")));
    // Compute stats
    accessEvents = AnalyzeAccessEvents("compute stats functional_kudu.testtbl");
    Assert.assertEquals(accessEvents, Sets.newHashSet(new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "ALTER"), new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "SELECT")));
    // Describe
    accessEvents = AnalyzeAccessEvents("describe functional_kudu.testtbl");
    Assert.assertEquals(accessEvents, Sets.newHashSet(new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "ANY")));
    // Describe formatted
    accessEvents = AnalyzeAccessEvents("describe formatted functional_kudu.testtbl");
    Assert.assertEquals(accessEvents, Sets.newHashSet(new TAccessEvent("functional_kudu.testtbl", TCatalogObjectType.TABLE, "ANY")));
}

