    okDescribe(tableName, style, new String[] { "id" }, ALLTYPES_COLUMNS_WITHOUT_ID, onColumn("functional", "alltypes", "id", TPrivilegeLevel.SELECT)).error(accessError("functional.alltypes"));
    // Describe table extended.
