    okDescribe(tableName, style, new String[] { "id" }, (String[]) ArrayUtils.addAll(ALLTYPES_COLUMNS_WITHOUT_ID, new String[] { "Location:" }), onColumn("functional", "alltypes", "id", TPrivilegeLevel.SELECT)).error(accessError("functional.alltypes"));
    // Describe view.
