        authzTest.ok(onServer(privilege)).ok(onDatabase("functional", privilege)).ok(onTable("functional", "allcomplextypes", privilege));
    }
    authzTest.ok(onColumn("functional", "allcomplextypes", "int_struct_col", TPrivilegeLevel.SELECT)).error(accessError("functional.allcomplextypes"));
