    testToSql("select * from functional.alltypes where not exists " + "(select * from functional.alltypestiny)", "SELECT * FROM functional.alltypes WHERE NOT EXISTS " + "(SELECT * FROM functional.alltypestiny)");
    // Multiple nesting levels
    testToSql("select * from functional.alltypes where id in " + "(select id from functional.alltypestiny where int_col = " + "(select avg(int_col) from functional.alltypesagg))", "SELECT * FROM functional.alltypes WHERE id IN " + "(SELECT id FROM functional.alltypestiny WHERE int_col = " + "(SELECT avg(int_col) FROM functional.alltypesagg))");
