// Test the log2/PowerOf2 functions
@Test
public void testPowersOf2() {
    // Power-of-two
    assertEquals(8, BitUtil.log2Ceiling(256));
    // Power-of-two
    assertEquals(256, BitUtil.roundUpToPowerOf2(256));
    // Rounds up
    assertEquals(4, BitUtil.log2Ceiling(10));
    // Rounds up
    assertEquals(16, BitUtil.roundUpToPowerOf2(10));
    // > 32bit number
    assertEquals(33, BitUtil.log2Ceiling(8L * 1000L * 1000L * 1000L));
    assertEquals(8L * 1024L * 1024L * 1024L, // > 32bit number
    BitUtil.roundUpToPowerOf2(8L * 1000L * 1000L * 1000L));
    // Minimum valid input
    assertEquals(0, BitUtil.log2Ceiling(1));
    // Minimum valid input
    assertEquals(1, BitUtil.roundUpToPowerOf2(1));
    // Maximum valid input
    assertEquals(63, BitUtil.log2Ceiling(Long.MAX_VALUE));
    // Overflow to -2^62.
    assertEquals(-0x8000000000000000L, BitUtil.roundUpToPowerOf2(Long.MAX_VALUE));
    // Maximum non-overflow output: 2^62.
    assertEquals(0x8000000000000000L, BitUtil.roundUpToPowerOf2(0x8000000000000000L - 1));
}

