        fail();
    } catch (ArrayIndexOutOfBoundsException e) {
    }
    try {
        arr.removeLast(Integer.MAX_VALUE);
        fail();
    } catch (ArrayIndexOutOfBoundsException e) {
    }
    try {
        arr.removeLast(-1);
        fail();
    } catch (ArrayIndexOutOfBoundsException e) {
    }
    arr.removeLast(0);
    assertNaturalNumberSequence(arr, 32);
    // Test set()
    arr.set(0, -1);
    assert arr.get(0) == -1;
    arr.set(31, -1);
    assert arr.get(31) == -1;
    try {
        arr.set(-1, -1);
        fail();
    } catch (ArrayIndexOutOfBoundsException e) {
    }
    try {
        arr.set(32, -1);
        fail();
    } catch (ArrayIndexOutOfBoundsException e) {
    }
    // Test clear()
    arr.clear();
    assertNaturalNumberSequence(arr, 0);
}

